"""Build WORKSPACE/AGENTS.md for Codex (no @import support)."""

from __future__ import annotations

import logging
import os
from pathlib import Path
from typing import Optional

log = logging.getLogger("daftar.agents_md")

HEADER = (
    "<!-- Generated by Daftar: edit the source files "
    "(rules/, persona/, knowledge/), not this file. -->\n"
)


def _lock_path(workspace: Path) -> Path:
    return Path(workspace) / "knowledge" / ".agents_md.lock"


def source_files(workspace: Path, persona_file: Path) -> list[Path]:
    ws = Path(workspace)
    files = [
        ws / "rules" / "BASE_RULES.md",
        Path(persona_file),
        ws / "rules" / "MY_RULES.md",
        ws / "knowledge" / "MAP.md",
    ]
    # Optional projects index line/file if present
    for extra in (
        ws / "knowledge" / "projects_index.md",
        ws / "knowledge" / "PROJECTS.md",
    ):
        if extra.exists():
            files.append(extra)
    return files


def _read(path: Path) -> str:
    if not path.exists():
        return ""
    try:
        return path.read_text(encoding="utf-8").rstrip() + "\n"
    except OSError:
        return ""


def build_agents_md(workspace: Path, persona_file: Path) -> str:
    """Compose AGENTS.md body from source files."""
    parts = [HEADER, ""]
    labels = [
        ("Base rules", Path(workspace) / "rules" / "BASE_RULES.md"),
        ("Persona", Path(persona_file)),
        ("My rules", Path(workspace) / "rules" / "MY_RULES.md"),
        ("Knowledge map", Path(workspace) / "knowledge" / "MAP.md"),
    ]
    for title, path in labels:
        body = _read(path)
        if not body.strip():
            continue
        if not body.lstrip().startswith("# "):
            parts.append(f"# {title}\n")
        parts.append(body)
        if not body.endswith("\n"):
            parts.append("\n")
    # Projects index extras
    for extra in (
        Path(workspace) / "knowledge" / "projects_index.md",
        Path(workspace) / "knowledge" / "PROJECTS.md",
    ):
        body = _read(extra)
        if body.strip():
            parts.append("# Projects index\n")
            parts.append(body)
    return "".join(parts)


def needs_regen(workspace: Path, persona_file: Path, dest: Optional[Path] = None) -> bool:
    """True when AGENTS.md differs from what the sources produce now.

    Content comparison (a few KB) instead of mtimes, so switching the persona
    file of a profile, or two profiles sharing a workspace, is always picked up.
    """
    dest = dest or (Path(workspace) / "AGENTS.md")
    try:
        current = dest.read_text(encoding="utf-8")
    except OSError:
        return True
    return current != build_agents_md(workspace, persona_file)


def write_agents_md(
    workspace: Path,
    persona_file: Path,
    *,
    force: bool = False,
) -> Path:
    """Write AGENTS.md under a file lock. Returns the path."""
    ws = Path(workspace)
    dest = ws / "AGENTS.md"
    persona = Path(persona_file)
    if not force and not needs_regen(ws, persona, dest):
        return dest

    lock = _lock_path(ws)
    lock.parent.mkdir(parents=True, exist_ok=True)
    lock.touch(exist_ok=True)
    try:
        import fcntl

        with open(lock, "a+", encoding="utf-8") as fh:
            fcntl.flock(fh, fcntl.LOCK_EX)
            try:
                # Re-check under lock
                if force or needs_regen(ws, persona, dest):
                    text = build_agents_md(ws, persona)
                    tmp = dest.with_suffix(".md.tmp")
                    tmp.write_text(text, encoding="utf-8")
                    os.replace(tmp, dest)
                    log.info("AGENTS.md regenerated (%d bytes) persona=%s", len(text), persona.name)
            finally:
                fcntl.flock(fh, fcntl.LOCK_UN)
    except ImportError:
        text = build_agents_md(ws, persona)
        dest.write_text(text, encoding="utf-8")
    return dest


def ensure_agents_md(
    workspace: Path,
    *,
    persona_file: Optional[Path] = None,
    cfg: Optional[dict[str, str]] = None,
    force: bool = False,
) -> Path:
    """Public entry: resolve persona from cfg if needed, then write."""
    from .config import persona_path

    persona = Path(persona_file) if persona_file else persona_path(cfg, Path(workspace))
    return write_agents_md(Path(workspace), persona, force=force)
